CREATE TABLE IF NOT EXISTS p14_promotion_states (season_index INT NOT NULL,server_id BIGINT NOT NULL,player_id BIGINT NOT NULL,qualification_hash CHAR(64) NOT NULL,calendar_hash CHAR(64) NOT NULL,stage_start BIGINT NOT NULL,stage_end BIGINT NOT NULL,eligible_at BIGINT NOT NULL,rules_json LONGTEXT NOT NULL,rules_hash CHAR(64) NOT NULL,points BIGINT NOT NULL,score BIGINT NOT NULL,last_grant_at BIGINT NOT NULL,created_at BIGINT NOT NULL,updated_at BIGINT NOT NULL,source_hash CHAR(64) NOT NULL,PRIMARY KEY(season_index,server_id,player_id)) ENGINE=InnoDB;
